 * of it is left. Pure functions over UTC instants, shared by the renewal job
 * and the mid-period changes in `BillingService`.
 */
import type { BillingInterval } from "@/types/billing";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Months a period of this interval spans — the multiplier in every charge. */
export function monthsInPeriod(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/**
 * Adds calendar months in UTC, keeping the time of day and clamping to the
 * target month's last day (31 Jan + 1 month → 28 Feb).
 */
export function addMonths(from: Date, months: number): Date {
  const total = from.getUTCFullYear() * 12 + from.getUTCMonth() + months;
  const year = Math.floor(total / 12);
  const month = total - year * 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();

  const result = new Date(from.getTime());
  result.setUTCFullYear(year, month, Math.min(from.getUTCDate(), lastDay));
  return result;
}

/** The end of a period that starts at `start`. */
export function periodEndFor(start: Date, interval: BillingInterval): Date {
  return addMonths(start, monthsInPeriod(interval));
}

/** Full charge for one period, in cents. */
export function fullPeriodChargeCents(
  priceCentsPerSeatMonthly: number,
  seats: number,
  interval: BillingInterval,
): number {
  return priceCentsPerSeatMonthly * seats * monthsInPeriod(interval);
}

/**
 * Scales a full-period amount by the days left over the days in the period,
 * rounded down to whole cents. Days left are whole or started days from `at`
 * to the period end, and none once the end has been reached.
