import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap } from "@/types/event";

let cleanup: () => void;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

function setSubscription(tenant: Tenant, patch: Partial<typeof subscriptions.$inferInsert>) {
  getDb().update(subscriptions).set(patch).where(eq(subscriptions.orgId, tenant.org.id)).run();
}

describe("period arithmetic", () => {
  it("clamps month ends and carries the clamped day forward", () => {
    const jan31 = new Date("2026-01-31T10:30:00.000Z");
    const feb = addMonths(jan31, 1);
    expect(feb.toISOString()).toBe("2026-02-28T10:30:00.000Z");
    expect(addMonths(feb, 1).toISOString()).toBe("2026-03-28T10:30:00.000Z");
    expect(addMonths(new Date("2028-02-29T00:00:00.000Z"), 12).toISOString()).toBe(
      "2029-02-28T00:00:00.000Z",
    );
    expect(addMonths(new Date("2026-12-15T00:00:00.000Z"), 1).toISOString()).toBe(
      "2027-01-15T00:00:00.000Z",
    );
  });

  it("prorates by started days, rounding down", () => {
    const start = new Date("2026-01-01T00:00:00.000Z");
    const end = new Date("2026-01-31T00:00:00.000Z");
    const at = new Date("2026-01-16T02:00:00.000Z"); // 14 days 22 hours left
    expect(prorateCents(3000, start, end, at)).toBe(1500);
    expect(prorateCents(1000, start, end, at)).toBe(500);
    expect(prorateCents(1000, start, end, end)).toBe(0);
  });
});

describe("jobs/billing-renewal-job", () => {
  it("renews every elapsed period with one invoice each, and is replay-safe", async () => {
    const tenant = await createTenant("renew-three", "starter");
    setSubscription(tenant, {
      status: "active",
      seats: 4,
      currentPeriodStart: "2026-01-31T12:00:00.000Z",
      currentPeriodEnd: "2026-02-28T12:00:00.000Z",
    });

    const issued: TaskflowEventMap["billing.invoice_issued"][] = [];
    const off = subscribe("billing.invoice_issued", (payload) => {
      issued.push(payload);
    });

    const now = new Date("2026-04-30T00:00:00.000Z");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);
    off();

    const sub = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(sub?.currentPeriodStart).toBe("2026-04-28T12:00:00.000Z");
    expect(sub?.currentPeriodEnd).toBe("2026-05-28T12:00:00.000Z");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-04-28T12:00:00.000Z",
      "2026-03-28T12:00:00.000Z",
      "2026-02-28T12:00:00.000Z",
    ]);
    expect(invoices.every((invoice) => invoice.amountCents === 900 * 4)).toBe(true);
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(3);
    expect(issued).toHaveLength(3);
  });

  it("invoices annual periods at twelve months", async () => {
    const tenant = await createTenant("renew-annual", "growth");
    setSubscription(tenant, {
      status: "active",
      interval: "annual",
      seats: 2,
      currentPeriodStart: "2025-03-01T00:00:00.000Z",
      currentPeriodEnd: "2026-03-01T00:00:00.000Z",
    });

    await runBillingRenewalJob(new Date("2026-03-01T00:00:00.000Z"));

    const [invoice] = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoice?.amountCents).toBe(1_900 * 2 * 12);
    expect(invoice?.periodEnd).toBe("2027-03-01T00:00:00.000Z");
  });

  it("moves free periods on without invoices and leaves trials alone", async () => {
    const free = await createTenant("renew-free", "free");
    setSubscription(free, {
      currentPeriodStart: "2026-01-01T00:00:00.000Z",
      currentPeriodEnd: "2026-02-01T00:00:00.000Z",
    });
    const trial = await createTenant("renew-trial", "growth");
    setSubscription(trial, { currentPeriodEnd: "2026-01-01T00:00:00.000Z" });

    await runBillingRenewalJob(new Date("2026-02-15T00:00:00.000Z"));

    expect((await subscriptionRepo.findSubscription(free.org.id))?.currentPeriodEnd).toBe(
      "2026-03-01T00:00:00.000Z",
    );
    expect(await invoiceRepo.listInvoices(free.org.id)).toHaveLength(0);
    expect((await subscriptionRepo.findSubscription(trial.org.id))?.currentPeriodEnd).toBe(
      "2026-01-01T00:00:00.000Z",
    );
    expect(await invoiceRepo.listInvoices(trial.org.id)).toHaveLength(0);
  });

  it("ends a cancellation on its date, once", async () => {
    const tenant = await createTenant("renew-cancel", "growth");
    setSubscription(tenant, {
      status: "canceled",
      cancelAt: "2026-06-10T00:00:00.000Z",
      currentPeriodStart: "2026-05-01T00:00:00.000Z",
      currentPeriodEnd: "2026-06-01T00:00:00.000Z",
    });

    const changes: TaskflowEventMap["billing.plan_changed"][] = [];
    const off = subscribe("billing.plan_changed", (payload) => {
      if (payload.orgId === tenant.org.id) changes.push(payload);
    });

    await runBillingRenewalJob(new Date("2026-06-05T00:00:00.000Z"));
    expect((await subscriptionRepo.findSubscription(tenant.org.id))?.status).toBe("canceled");

    const now = new Date("2026-06-12T00:00:00.000Z");
    await runBillingRenewalJob(now);
    await runBillingRenewalJob(now);
    off();

    expect(await subscriptionRepo.findSubscription(tenant.org.id)).toMatchObject({
      plan: "free",
      status: "active",
      cancelAt: null,
      currentPeriodStart: "2026-06-10T00:00:00.000Z",
      currentPeriodEnd: "2026-07-10T00:00:00.000Z",
    });
    expect(changes).toHaveLength(1);
    expect(changes[0]).toMatchObject({ from: "growth", to: "free", actorId: null });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });
});

describe("mid-period changes", () => {
